-- 주 DB 스키마(PostgreSQL). 코드 저장소 src/main/resources/db/migration/V1__init.sql과 같은 내용이다(스텝 23, 2026-10-13 지원 결정).
-- 스텝 22까지 이 파일은 Crowfoot 문서 665 버전 79에서 내보낸 MySQL DDL이었다. 표·칸·관계는 같고 타입과 문법만 PostgreSQL로 바꿨다(erd/README.md).
-- 주 DB 스키마 (PostgreSQL 17 + pgvector, 스텝 23, 2026-10-13 지원 결정: MySQL과 추천 DB를 합침, research R-02).
-- MySQL 때의 V1(Crowfoot 문서 665에서 내보낸 DDL)·V3(post.content_text)과 추천 DB의 post_embedding을 합친 지금 스키마다.
-- MySQL에서 바꾼 것
--   번호: AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY(옛 데이터를 번호째 옮길 수 있게 BY DEFAULT)
--   참/거짓: TINYINT(1) → BOOLEAN, 긴 글자: MEDIUMTEXT → TEXT, 시각: DATETIME → TIMESTAMP(0), DATETIME(6) → TIMESTAMP(6)
--   대소문자 무시 비교(MySQL utf8mb4_0900_ai_ci가 하던 것): 이메일·닉네임·블로그 주소·카테고리·태그·금칙어 이름은 CITEXT.
--     CITEXT는 길이가 없어 길이는 CHECK로 막는다. 악센트는 구분한다(Café ≠ cafe).
--   updated_at의 ON UPDATE CURRENT_TIMESTAMP는 없다. 엔티티를 고치면 JPA(@LastModifiedDate)가 채운다.
--   표·칸 설명: COMMENT → COMMENT ON

CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE member (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    profile_image_id BIGINT,
    email CITEXT,
    password_hash VARCHAR(100),
    nickname CITEXT NOT NULL,
    role VARCHAR(10) NOT NULL DEFAULT 'USER',
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    suspended_until TIMESTAMP(0),
    withdrawn_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_member_email UNIQUE (email),
    CONSTRAINT uk_member_nickname UNIQUE (nickname),
    CONSTRAINT ck_member_role CHECK (role IN ('USER', 'ADMIN')),
    CONSTRAINT ck_member_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'WITHDRAWN')),
    CONSTRAINT ck_member_email_length CHECK (char_length(email) <= 255),
    CONSTRAINT ck_member_nickname_length CHECK (char_length(nickname) <= 20)
);
CREATE TABLE social_account (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    member_id BIGINT NOT NULL,
    provider VARCHAR(10) NOT NULL,
    provider_user_id VARCHAR(100) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_social_account_provider_provider_user_id UNIQUE (provider, provider_user_id),
    CONSTRAINT uk_social_account_member_id_provider UNIQUE (member_id, provider),
    CONSTRAINT ck_social_account_provider CHECK (provider IN ('KAKAO', 'GOOGLE'))
);
CREATE TABLE email_verification (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    email VARCHAR(255) NOT NULL,
    code VARCHAR(10) NOT NULL,
    expires_at TIMESTAMP(0) NOT NULL,
    verified_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);
CREATE TABLE password_reset_token (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    member_id BIGINT NOT NULL,
    token_hash VARCHAR(64) NOT NULL,
    expires_at TIMESTAMP(0) NOT NULL,
    used_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_password_reset_token_token_hash UNIQUE (token_hash)
);
CREATE TABLE image (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    uploader_id BIGINT NOT NULL,
    path VARCHAR(255) NOT NULL,
    thumbnail_path VARCHAR(255),
    original_name VARCHAR(255) NOT NULL,
    content_type VARCHAR(20) NOT NULL,
    size BIGINT NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT ck_image_size CHECK (size <= 10485760)
);
CREATE TABLE blog (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    moved_to_blog_id BIGINT,
    profile_image_id BIGINT,
    member_id BIGINT NOT NULL,
    address CITEXT NOT NULL,
    name VARCHAR(50) NOT NULL,
    description VARCHAR(500),
    is_primary BOOLEAN NOT NULL DEFAULT FALSE,
    skin VARCHAR(20) NOT NULL DEFAULT 'BASIC',
    list_layout VARCHAR(10) NOT NULL DEFAULT 'LIST',
    is_restricted BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    primary_owner_id BIGINT GENERATED ALWAYS AS (CASE WHEN is_primary AND deleted_at IS NULL THEN member_id END) STORED,
    total_visitor_count BIGINT NOT NULL DEFAULT 0,
    accent_color VARCHAR(10) NOT NULL DEFAULT 'BLUE',
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_address UNIQUE (address),
    CONSTRAINT uk_blog_primary_owner_id UNIQUE (primary_owner_id),
    CONSTRAINT ck_blog_list_layout CHECK (list_layout IN ('LIST', 'THUMBNAIL')),
    CONSTRAINT ck_blog_accent_color CHECK (accent_color IN ('BLUE', 'GREEN', 'ORANGE', 'PINK', 'PURPLE', 'GRAY')),
    CONSTRAINT ck_blog_address_length CHECK (char_length(address) <= 32)
);
CREATE TABLE category (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    parent_id BIGINT,
    blog_id BIGINT NOT NULL,
    name CITEXT NOT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    is_private BOOLEAN NOT NULL DEFAULT FALSE,
    parent_key BIGINT GENERATED ALWAYS AS (COALESCE(parent_id, 0)) STORED NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_category_blog_id_parent_key_name UNIQUE (blog_id, parent_key, name),
    CONSTRAINT ck_category_name_length CHECK (char_length(name) <= 30)
);
CREATE TABLE post (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    category_id BIGINT,
    thumbnail_image_id BIGINT,
    title VARCHAR(200) NOT NULL,
    content_html TEXT NOT NULL,
    content_text TEXT NOT NULL,
    summary VARCHAR(300),
    status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
    visibility VARCHAR(20) NOT NULL DEFAULT 'PUBLIC',
    topic VARCHAR(20),
    published_at TIMESTAMP(6),
    scheduled_at TIMESTAMP(0),
    view_count BIGINT NOT NULL DEFAULT 0,
    like_count INT NOT NULL DEFAULT 0,
    comment_count INT NOT NULL DEFAULT 0,
    is_comment_allowed BOOLEAN NOT NULL DEFAULT TRUE,
    is_blinded BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT ck_post_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'SCHEDULED')),
    CONSTRAINT ck_post_visibility CHECK (visibility IN ('PUBLIC', 'PRIVATE', 'SUBSCRIBERS')),
    CONSTRAINT ck_post_topic CHECK (topic IS NULL OR topic IN ('IT_DEV', 'TRAVEL', 'FOOD', 'DAILY', 'REVIEW', 'HOBBY', 'FINANCE', 'HEALTH', 'CULTURE', 'EDUCATION'))
);
CREATE TABLE tag (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    name CITEXT NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_tag_blog_id_name UNIQUE (blog_id, name),
    CONSTRAINT ck_tag_name_length CHECK (char_length(name) <= 30)
);
CREATE TABLE post_tag (
    post_id BIGINT NOT NULL,
    tag_id BIGINT NOT NULL,
    PRIMARY KEY (post_id, tag_id)
);
CREATE TABLE view_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    post_id BIGINT NOT NULL,
    viewer_key VARCHAR(64) NOT NULL,
    viewed_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);
CREATE TABLE post_like (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    post_id BIGINT NOT NULL,
    member_id BIGINT NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_post_like_member_id_post_id UNIQUE (member_id, post_id)
);
CREATE TABLE comment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    parent_id BIGINT,
    post_id BIGINT NOT NULL,
    member_id BIGINT NOT NULL,
    content VARCHAR(1000) NOT NULL,
    is_secret BOOLEAN NOT NULL DEFAULT FALSE,
    is_blinded BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);
CREATE TABLE guestbook (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    parent_id BIGINT,
    blog_id BIGINT NOT NULL,
    member_id BIGINT NOT NULL,
    content VARCHAR(1000) NOT NULL,
    is_secret BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);
CREATE TABLE subscription (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    member_id BIGINT NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_subscription_member_id_blog_id UNIQUE (member_id, blog_id)
);
CREATE TABLE notification (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    receiver_id BIGINT NOT NULL,
    type VARCHAR(20) NOT NULL,
    target_type VARCHAR(20) NOT NULL,
    target_id BIGINT NOT NULL,
    message VARCHAR(255) NOT NULL,
    read_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT ck_notification_type CHECK (type IN ('COMMENT', 'REPLY', 'LIKE', 'SUBSCRIBE', 'SANCTION')),
    CONSTRAINT ck_notification_target_type CHECK (target_type IN ('POST', 'COMMENT', 'BLOG', 'MEMBER'))
);
CREATE TABLE report (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    reporter_id BIGINT NOT NULL,
    target_type VARCHAR(20) NOT NULL,
    target_id BIGINT NOT NULL,
    reason VARCHAR(20) NOT NULL,
    description VARCHAR(500),
    status VARCHAR(10) NOT NULL DEFAULT 'PENDING',
    result VARCHAR(20),
    processed_at TIMESTAMP(0),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_report_reporter_id_target_type_target_id UNIQUE (reporter_id, target_type, target_id),
    CONSTRAINT ck_report_target_type CHECK (target_type IN ('POST', 'COMMENT', 'BLOG')),
    CONSTRAINT ck_report_reason CHECK (reason IN ('SPAM', 'ADULT', 'ABUSE', 'COPYRIGHT', 'ETC')),
    CONSTRAINT ck_report_etc_description CHECK (reason <> 'ETC' OR description IS NOT NULL),
    CONSTRAINT ck_report_status CHECK (status IN ('PENDING', 'DONE')),
    CONSTRAINT ck_report_result CHECK (result IS NULL OR result IN ('BLIND', 'RESTRICT_BLOG', 'SUSPEND', 'REJECT'))
);
CREATE TABLE moderation_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    admin_id BIGINT NOT NULL,
    action VARCHAR(20) NOT NULL,
    target_type VARCHAR(20) NOT NULL,
    target_id BIGINT NOT NULL,
    reason VARCHAR(20),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    reason_detail VARCHAR(200),
    PRIMARY KEY (id),
    CONSTRAINT ck_moderation_log_action CHECK (action IN ('BLIND', 'UNBLIND', 'SUSPEND', 'UNSUSPEND', 'RESTRICT_BLOG', 'UNRESTRICT_BLOG', 'REJECT_REPORT')),
    CONSTRAINT ck_moderation_log_target_type CHECK (target_type IN ('POST', 'COMMENT', 'BLOG', 'MEMBER', 'REPORT')),
    CONSTRAINT ck_moderation_log_reason CHECK (reason IS NULL OR reason IN ('SPAM', 'ADULT', 'ABUSE', 'COPYRIGHT', 'ETC')),
    CONSTRAINT ck_moderation_log_sanction_reason CHECK (action NOT IN ('BLIND', 'SUSPEND', 'RESTRICT_BLOG') OR reason IS NOT NULL),
    CONSTRAINT ck_moderation_log_etc_detail CHECK (reason IS NULL OR reason <> 'ETC' OR reason_detail IS NOT NULL)
);
CREATE TABLE notice (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    admin_id BIGINT NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);
CREATE TABLE post_bookmark (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    post_id BIGINT NOT NULL,
    member_id BIGINT NOT NULL,
    title_snapshot VARCHAR(200) NOT NULL,
    blog_name_snapshot VARCHAR(50) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_post_bookmark_member_id_post_id UNIQUE (member_id, post_id)
);
CREATE TABLE blog_visit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    visit_date DATE NOT NULL,
    visitor_key VARCHAR(64) NOT NULL,
    referrer_type VARCHAR(10) NOT NULL DEFAULT 'DIRECT',
    referrer_host VARCHAR(100) NOT NULL DEFAULT '',
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_visit_blog_id_visit_date_visitor_key UNIQUE (blog_id, visit_date, visitor_key),
    CONSTRAINT ck_blog_visit_referrer_type CHECK (referrer_type IN ('SEARCH','SNS','DIRECT','INTERNAL','OTHER'))
);
CREATE TABLE blog_daily_stat (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    stat_date DATE NOT NULL,
    visitor_count INT NOT NULL DEFAULT 0,
    view_count INT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_daily_stat_blog_id_stat_date UNIQUE (blog_id, stat_date)
);
CREATE TABLE blog_referrer_daily (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    stat_date DATE NOT NULL,
    referrer_type VARCHAR(10) NOT NULL,
    referrer_host VARCHAR(100) NOT NULL DEFAULT '',
    visit_count INT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_referrer_daily_key UNIQUE (blog_id, stat_date, referrer_type, referrer_host)
);
CREATE TABLE blog_blocked_member (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blocked_member_id BIGINT NOT NULL,
    blog_id BIGINT NOT NULL,
    memo VARCHAR(200),
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_block_blog_id_blocked_member_id UNIQUE (blog_id, blocked_member_id)
);
CREATE TABLE blog_banned_word (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    word CITEXT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_banned_word_blog_id_word UNIQUE (blog_id, word),
    CONSTRAINT ck_blog_banned_word_word_length CHECK (char_length(word) <= 30)
);
CREATE TABLE blog_sidebar_module (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    blog_id BIGINT NOT NULL,
    module_type VARCHAR(20) NOT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    is_visible BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_blog_sidebar_module_blog_id_module_type UNIQUE (blog_id, module_type),
    CONSTRAINT ck_blog_sidebar_module_module_type CHECK (module_type IN ('PROFILE', 'CATEGORY', 'TAG', 'RECENT_POST', 'RECENT_COMMENT', 'VISITOR', 'POPULAR_POST', 'SUBSCRIBE')),
    CONSTRAINT ck_blog_sidebar_module_profile_visible CHECK (module_type <> 'PROFILE' OR is_visible)
);

