-- 글 임베딩 (비슷한 글 OWN-06, 의미 검색 OWN-07). 발행 글이면 공개 범위와 상관없이 두고, 볼 수 있는지는 찾을 때 거른다.
-- 글을 지우는 것은 소프트 삭제라 애플리케이션이 이 행도 지운다. 글 행이 정말 지워지면 외래 키가 함께 지운다.
CREATE TABLE post_embedding (
    post_id      BIGINT PRIMARY KEY REFERENCES post (id) ON DELETE CASCADE,
    embedding    vector(1024) NOT NULL,
    text_version SMALLINT     NOT NULL,
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT now()
);
COMMENT ON TABLE post_embedding IS '글 임베딩-----Ollama bge-m3(1024차원)';
COMMENT ON COLUMN post_embedding.text_version IS '넣은 글자 방식-----1 = 제목+본문, 2 = 제목+태그+본문(PostEmbeddingService.TEXT_VERSION). 다르면 서버가 뜰 때 다시 만든다';
-- 코사인 거리(<=>)로 가까운 글을 찾는 근사 최근접 이웃 인덱스(HNSW)
CREATE INDEX idx_post_embedding_embedding ON post_embedding USING hnsw (embedding vector_cosine_ops);

COMMENT ON TABLE member IS '회원-----이메일 가입·소셜 가입 회원. 탈퇴해도 행은 남는다';
COMMENT ON COLUMN member.id IS '회원 ID';
COMMENT ON COLUMN member.profile_image_id IS '프로필 이미지';
COMMENT ON COLUMN member.email IS '이메일-----이메일 가입 회원만 값이 있고 모두 인증됨. 소셜 가입·탈퇴 회원은 NULL';
COMMENT ON COLUMN member.password_hash IS '비밀번호 해시-----bcrypt';
COMMENT ON COLUMN member.nickname IS '닉네임';
COMMENT ON COLUMN member.role IS '역할-----가입은 항상 USER. ADMIN은 data.sql로만';
COMMENT ON COLUMN member.status IS '상태-----모든 로그인 경로에서 먼저 확인';
COMMENT ON COLUMN member.suspended_until IS '정지 종료 시각-----SUSPENDED + NULL = 영구 정지. 사유는 moderation_log 최신 SUSPEND 행';
COMMENT ON COLUMN member.withdrawn_at IS '탈퇴 시각';
COMMENT ON COLUMN member.created_at IS '가입 시각';
COMMENT ON COLUMN member.updated_at IS '수정 시각';
