COMMENT ON COLUMN email_verification.code IS '인증 코드';
COMMENT ON COLUMN email_verification.expires_at IS '만료 시각';
COMMENT ON COLUMN email_verification.verified_at IS '인증 완료 시각';
COMMENT ON COLUMN email_verification.created_at IS '생성 일시';
COMMENT ON TABLE password_reset_token IS '비밀번호 재설정 토큰';
