COMMENT ON COLUMN notice.created_at IS '생성 일시';
COMMENT ON COLUMN notice.updated_at IS '수정 일시';
COMMENT ON TABLE post_bookmark IS '저장-----회원이 저장한 글. 볼 수 없게 된 글도 행을 남기고 저장 시점 제목·블로그 이름만 보여 준다(헌법 원칙 II 예외)';
COMMENT ON COLUMN post_bookmark.id IS '저장 ID';
COMMENT ON COLUMN post_bookmark.post_id IS '글 ID';
COMMENT ON COLUMN post_bookmark.member_id IS '회원 ID';
COMMENT ON COLUMN post_bookmark.title_snapshot IS '저장 시점 글 제목';
COMMENT ON COLUMN post_bookmark.blog_name_snapshot IS '저장 시점 블로그 이름';
COMMENT ON COLUMN post_bookmark.created_at IS '저장 시각';
COMMENT ON TABLE blog_visit IS '블로그 방문-----블로그·날짜·방문자마다 한 행(하루 1회). 주인 본인 방문은 세지 않는다. 매일 새벽 blog_daily_stat·blog_referrer_daily로 모으고 7일 뒤 지운다';
COMMENT ON COLUMN blog_visit.id IS '블로그 방문 ID';
COMMENT ON COLUMN blog_visit.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_visit.visit_date IS '방문 날짜';
COMMENT ON COLUMN blog_visit.visitor_key IS '방문자 키-----회원 id 또는 익명 식별자(view_log와 같은 방식)';
COMMENT ON COLUMN blog_visit.referrer_type IS '유입 종류-----SEARCH, SNS, DIRECT, INTERNAL, OTHER';
COMMENT ON COLUMN blog_visit.referrer_host IS '유입 호스트-----Referer의 호스트. 직접 방문이면 빈 값';
COMMENT ON TABLE blog_daily_stat IS '블로그 일별 통계-----전날 blog_visit을 모은 일별 방문자 수와 글 조회 수. 어제 방문자와 일·주·월 그래프에 쓴다';
COMMENT ON COLUMN blog_daily_stat.id IS '블로그 일별 통계 ID';
COMMENT ON COLUMN blog_daily_stat.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_daily_stat.stat_date IS '날짜';
COMMENT ON COLUMN blog_daily_stat.visitor_count IS '방문자 수';
COMMENT ON COLUMN blog_daily_stat.view_count IS '글 조회 수';
COMMENT ON TABLE blog_referrer_daily IS '블로그 일별 유입 경로-----전날 blog_visit을 유입 종류·호스트별로 센 값';
COMMENT ON COLUMN blog_referrer_daily.id IS '블로그 일별 유입 경로 ID';
COMMENT ON COLUMN blog_referrer_daily.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_referrer_daily.stat_date IS '날짜';
COMMENT ON COLUMN blog_referrer_daily.referrer_type IS '유입 종류';
COMMENT ON COLUMN blog_referrer_daily.referrer_host IS '유입 호스트';
COMMENT ON COLUMN blog_referrer_daily.visit_count IS '방문 수';
COMMENT ON TABLE blog_blocked_member IS '차단 회원-----블로그 주인이 차단한 회원. 그 블로그에 댓글·방명록을 쓰거나 구독할 수 없다. 주인이 쓰는 기능이라 관리 이력에 남기지 않는다';
COMMENT ON COLUMN blog_blocked_member.id IS '차단 회원 ID';
COMMENT ON COLUMN blog_blocked_member.blocked_member_id IS '차단된 회원 ID';
COMMENT ON COLUMN blog_blocked_member.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_blocked_member.memo IS '메모';
COMMENT ON COLUMN blog_blocked_member.created_at IS '차단 시각';
COMMENT ON TABLE blog_banned_word IS '금칙어-----블로그별 금칙어. 최대 100개, 대소문자 무시 포함 검사';
COMMENT ON COLUMN blog_banned_word.id IS '금칙어 ID';
COMMENT ON COLUMN blog_banned_word.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_banned_word.word IS '금칙어';
COMMENT ON TABLE blog_sidebar_module IS '사이드바 모듈-----블로그 사이드바의 모듈 순서와 표시 여부. 블로그를 만들 때 8개 행을 함께 만든다(VISITOR·POPULAR_POST·SUBSCRIBE는 숨김). 모듈별 개수는 고정(최근 글·댓글·인기 글 5개)';
