COMMENT ON COLUMN blog_sidebar_module.blog_id IS '블로그 ID';
COMMENT ON COLUMN blog_sidebar_module.module_type IS '모듈 종류';
COMMENT ON COLUMN blog_sidebar_module.sort_order IS '순서';
COMMENT ON COLUMN blog_sidebar_module.is_visible IS '표시 여부-----PROFILE은 항상 1';
COMMENT ON COLUMN blog_sidebar_module.updated_at IS '수정 일시';
